#!/usr/bin/env python3
"""Generate build.ninja for ReverseApoc.

Phase 2 skeleton: only verification targets exist yet. Re-run after `reverseapoc ingest` so
`parse-le` picks up the executables present in orig/.

    python configure.py [--orig DIR] [--output build.ninja]
"""

from __future__ import annotations

import argparse
import os
import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent

# The build.ninja text; render() fills {orig} in the check_orig and rebuild commands.
HEADER = """\
# build.ninja -- generated by configure.py; do not edit, re-run `python configure.py`.
#
# Phase 2 skeleton: verification targets only.
#   ninja check-orig   verify orig/ against config/targets.toml (size, CRC32, MD5, SHA-1)
#   ninja parse-le     print the LE layout of every EXE found in orig/ at configure time
#   ninja verify       rebuild every target into build/ and check its SHA-1 (config/targets.toml)
#
# Compilation rules arrive in Phase 5: wcc386 (Watcom 10.x, user-supplied) under wibo,
# OMF -> ELF conversion, objdiff, page splice back into the LE image, whole-EXE SHA-1 check.

ninja_required_version = 1.10
builddir = build

rule check_orig
  command = uv run reverseapoc check-orig --orig {orig}
  description = CHECK-ORIG orig/
  pool = console

rule parse_le
  command = uv run reverseapoc parse-le $in
  description = PARSE-LE $in
  pool = console

rule rebuild
  command = uv run reverseapoc rebuild --orig {orig}
  description = REBUILD build/
  pool = console

# Outputs under $builddir/always/ are never written, so these edges run every time they are
# requested; check-orig, verify and parse-le are phony aliases for them.
"""


class ConfigureError(ValueError):
    """build.ninja cannot safely carry the named path."""


# ninja 1.11 (the container's) has no escape for these in a build path.
_UNESCAPABLE = ("|", "\n", "\r")

# The orig dir is written unquoted into the check-orig and rebuild commands, which /bin/sh runs
# in the container and CreateProcess splits on Windows; no quoting is portable across both, so
# only characters that need none are accepted. `:` covers a drive letter (see _relative).
_SAFE_ORIG = re.compile(r"[A-Za-z0-9._/:-]+")


def ninja_path(path: str) -> str:
    """Escape a path for use in a ninja build line."""
    bad = next((c for c in _UNESCAPABLE if c in path), None)
    if bad is not None:
        raise ConfigureError(
            f"{path!r} holds {bad!r}, which ninja 1.11 (the container's) cannot escape in a "
            "build path; rename the file"
        )
    return path.replace("$", "$$").replace(" ", "$ ").replace(":", "$:")


def _check_orig_dir(orig: str) -> str:
    if not _SAFE_ORIG.fullmatch(orig):
        raise ConfigureError(
            f"orig path {orig!r} is written unquoted into the check-orig and verify commands, "
            "which /bin/sh runs in the container and CreateProcess splits on Windows, so only "
            "ASCII letters, digits and . _ - / : are accepted; rename or move the directory"
        )
    return orig


def find_executables(orig_dir: Path) -> list[Path]:
    """*.exe files directly in `orig_dir` (any case), sorted by name ignoring case."""
    if not orig_dir.is_dir():
        return []
    exes = [p for p in orig_dir.iterdir() if p.is_file() and p.suffix.lower() == ".exe"]
    return sorted(exes, key=lambda p: p.name.casefold())


def render(exes: list[str], *, orig: str = "orig") -> str:
    """build.ninja text for executables given as paths relative to the build.ninja directory.
    `orig` is the orig directory relative to the build.ninja directory, like the exe paths.

    Raises ConfigureError for a path build.ninja cannot safely carry."""
    lines = [
        HEADER.format(orig=_check_orig_dir(orig)),
        "build $builddir/always/check-orig: check_orig",
        "build check-orig: phony $builddir/always/check-orig",
        "build $builddir/always/verify: rebuild",
        "build verify: phony $builddir/always/verify",
        "",
    ]
    outputs = []
    for exe in exes:
        src = ninja_path(exe)  # first, so a refusal names the whole path
        out = f"$builddir/always/parse-le/{ninja_path(Path(exe).name)}"
        lines.append(f"build {out}: parse_le {src}")
        outputs.append(out)
    lines.append(" ".join(["build parse-le: phony", *outputs]))
    lines += ["", "default check-orig", ""]
    return "\n".join(lines)


def _relative(path: Path, base: Path) -> str:
    try:
        return Path(os.path.relpath(path, base)).as_posix()
    except ValueError:  # different drive on Windows
        return path.resolve().as_posix()


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Write build.ninja.")
    parser.add_argument("--orig", type=Path, default=ROOT / "orig")
    parser.add_argument("--output", type=Path, default=ROOT / "build.ninja")
    args = parser.parse_args(argv)
    base = args.output.resolve().parent
    exes = [_relative(p, base) for p in find_executables(args.orig)]
    try:
        text = render(exes, orig=_relative(args.orig, base))
    except ConfigureError as exc:
        print(f"configure.py: error: {exc}", file=sys.stderr)
        return 1
    args.output.write_text(text, encoding="utf-8", newline="\n")
    print(f"wrote {args.output} ({len(exes)} executable(s) for parse-le)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
